import{_ as a,o as n,c as l,a5 as o}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"Bing与IndexNow URL推送 — Z-BlogPHP 搜索引擎推送插件","description":"","frontmatter":{"标题":"ZBlogPHP 搜索引擎推送插件 — Bing与IndexNow URL推送","日期":"2026-07-11T00:00:00.000Z","修改日期":"2026-07-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["zblog主题插件"],"标签":["Bing推送","IndexNow","SEO优化","URL提交","Z-BlogPHP","搜索引擎收录","网站优化"]},"headers":[{"level":2,"title":"插件简介","slug":"插件简介","link":"#插件简介","children":[]},{"level":2,"title":"功能特性","slug":"功能特性","link":"#功能特性","children":[{"level":3,"title":"双通道独立推送","slug":"双通道独立推送","link":"#双通道独立推送","children":[]},{"level":3,"title":"新文章发布即时推送","slug":"新文章发布即时推送","link":"#新文章发布即时推送","children":[]},{"level":3,"title":"访客驱动定时推送","slug":"访客驱动定时推送","link":"#访客驱动定时推送","children":[]},{"level":3,"title":"数据库标记防重复推送","slug":"数据库标记防重复推送","link":"#数据库标记防重复推送","children":[]},{"level":3,"title":"Bing 剩余额度实时查询","slug":"bing-剩余额度实时查询","link":"#bing-剩余额度实时查询","children":[]},{"level":3,"title":"手动一键批量推送","slug":"手动一键批量推送","link":"#手动一键批量推送","children":[]},{"level":3,"title":"IndexNow 密钥文件自动管理","slug":"indexnow-密钥文件自动管理","link":"#indexnow-密钥文件自动管理","children":[]},{"level":3,"title":"外部 API 调用端点","slug":"外部-api-调用端点","link":"#外部-api-调用端点","children":[]},{"level":3,"title":"推送日志记录","slug":"推送日志记录","link":"#推送日志记录","children":[]},{"level":3,"title":"管理后台开关","slug":"管理后台开关","link":"#管理后台开关","children":[]}]},{"level":2,"title":"使用说明","slug":"使用说明","link":"#使用说明","children":[{"level":3,"title":"第一步：安装插件","slug":"第一步-安装插件","link":"#第一步-安装插件","children":[]},{"level":3,"title":"第二步：配置 Bing 推送","slug":"第二步-配置-bing-推送","link":"#第二步-配置-bing-推送","children":[]},{"level":3,"title":"第三步：配置 IndexNow 推送","slug":"第三步-配置-indexnow-推送","link":"#第三步-配置-indexnow-推送","children":[]},{"level":3,"title":"第四步：验证推送效果","slug":"第四步-验证推送效果","link":"#第四步-验证推送效果","children":[]}]},{"level":2,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":2,"title":"反馈与支持","slug":"反馈与支持","link":"#反馈与支持","children":[]},{"level":2,"title":"更新日志","slug":"更新日志","link":"#更新日志","children":[{"level":3,"title":"v1.0.0（2026-07-05）","slug":"v1-0-0-2026-07-05","link":"#v1-0-0-2026-07-05","children":[]}]}],"relativePath":"md/zblog主题插件/ZBlogPHP 搜索引擎推送插件 — Bing与IndexNow URL推送.md","filePath":"md/zblog主题插件/ZBlogPHP 搜索引擎推送插件 — Bing与IndexNow URL推送.md"}'),i={name:"md/zblog主题插件/ZBlogPHP 搜索引擎推送插件 — Bing与IndexNow URL推送.md"};function t(r,e,d,h,b,g){return n(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="bing与indexnow-url推送-—-z-blogphp-搜索引擎推送插件" tabindex="-1">Bing与IndexNow URL推送 — Z-BlogPHP 搜索引擎推送插件 <a class="header-anchor" href="#bing与indexnow-url推送-—-z-blogphp-搜索引擎推送插件" aria-label="Permalink to &quot;Bing与IndexNow URL推送 — Z-BlogPHP 搜索引擎推送插件&quot;">​</a></h1><blockquote><p>发布新文章时自动提交 URL 到 Bing Webmaster API 和 IndexNow 协议搜索引擎，支持 Bing、Yandex、Seznam、Naver 等多引擎同时推送，内置双通道独立配置、定时推送与手动一键批量推送，帮助网站快速被搜索引擎收录。</p></blockquote><p><strong>版本</strong>：v1.0.0<br><strong>适配</strong>：Z-BlogPHP 1.7.0+<br><strong>PHP</strong>：&gt;= 7.2<br><strong>作者</strong>：softbangong<br><strong>授权</strong>：不限制网站数量，下载安装后永久免费使用</p><h2 id="插件简介" tabindex="-1">插件简介 <a class="header-anchor" href="#插件简介" aria-label="Permalink to &quot;插件简介&quot;">​</a></h2><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-7.png" alt=""></p><p>本插件用于将 Z-BlogPHP 网站的新发布文章 URL 自动推送到搜索引擎，涵盖 Bing Webmaster Tools 的 URL 提交 API 和 IndexNow 协议（Bing、Yandex、Seznam、Naver），让搜索引擎第一时间知道网站内容更新，加速新文章的收录速度。</p><p>插件在后台提供了双 Tab 管理界面（Bing 推送 / IndexNow 推送），两个推送通道完全独立配置，可同时启用或按需单独开启。每条新文章发布时立即触发推送，同时通过访客访问前台页面自动驱动定时任务，按配置间隔持续推送待提交的 URL，无需额外设置 Cron 计划任务。</p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><h3 id="双通道独立推送" tabindex="-1">双通道独立推送 <a class="header-anchor" href="#双通道独立推送" aria-label="Permalink to &quot;双通道独立推送&quot;">​</a></h3><p>插件同时支持两大推送通道，在后台通过 Tab 切换独立管理：</p><table tabindex="0"><thead><tr><th>通道</th><th>覆盖引擎</th><th>API 端点</th></tr></thead><tbody><tr><td>Bing 推送</td><td>Bing</td><td>Bing Webmaster API (SubmitUrlbatch)</td></tr><tr><td>Bing 推送</td><td>Bing</td><td>Bing Webmaster API (SubmitUrlbatch)</td></tr></tbody></table><p>两个通道各自独立配置 API Key、推送间隔、每次推送数量和自动推送开关，互不干扰，可按需灵活组合使用。</p><h3 id="新文章发布即时推送" tabindex="-1">新文章发布即时推送 <a class="header-anchor" href="#新文章发布即时推送" aria-label="Permalink to &quot;新文章发布即时推送&quot;">​</a></h3><p>发布新文章时，插件通过 Z-BlogPHP 的 PostSucceed 钩子自动触发推送：</p><p>— 文章保存成功后立即调用 API 提交该文章 URL；<br> — Bing 和 IndexNow 两个通道各自独立响应，一条文章发布可同时推送到多个搜索引擎；<br> — 推送过程异步执行，不影响文章发布流程和后台操作体验。</p><h3 id="访客驱动定时推送" tabindex="-1">访客驱动定时推送 <a class="header-anchor" href="#访客驱动定时推送" aria-label="Permalink to &quot;访客驱动定时推送&quot;">​</a></h3><p>无需配置服务器 Cron 计划任务，插件利用访客访问前台页面时自动检查推送间隔：</p><p>— 当有访客访问网站前台 HTML 页面时，插件检查距上次推送是否已超过配置的时间间隔；<br> — 若已达间隔，自动从数据库中取出尚未推送的文章 URL 批量提交；<br> — 后台请求（管理页面、AJAX、CMD）和静态资源请求自动排除，不触发推送任务，避免无意义的 API 调用。</p><h3 id="数据库标记防重复推送" tabindex="-1">数据库标记防重复推送 <a class="header-anchor" href="#数据库标记防重复推送" aria-label="Permalink to &quot;数据库标记防重复推送&quot;">​</a></h3><p>插件在 Z-BlogPHP 文章表中自动添加 <code>bingis</code> 和 <code>indexnowis</code> 两个标记字段：</p><p>— 每次推送成功后标记对应文章为已推送，下次定时任务不再重复提交；<br> — 文章全部推送完毕后自动重置标记，确保后续新文章可正常进入推送队列；<br> — 手动推送和定时推送共享同一套标记机制，保证数据一致性。</p><h3 id="bing-剩余额度实时查询" tabindex="-1">Bing 剩余额度实时查询 <a class="header-anchor" href="#bing-剩余额度实时查询" aria-label="Permalink to &quot;Bing 剩余额度实时查询&quot;">​</a></h3><p>Bing 推送面板顶部展示当日剩余推送额度仪表盘：</p><p>— 通过 Bing Webmaster API 实时查询 DailyQuota 和已用量，计算当日剩余可推送条数；<br> — API 查询失败时自动回退到本地缓存数据，确保额度信息不间断展示；<br> — 仪表盘同时显示累计推送总数和上次推送时间，推送状态一目了然。</p><h3 id="手动一键批量推送" tabindex="-1">手动一键批量推送 <a class="header-anchor" href="#手动一键批量推送" aria-label="Permalink to &quot;手动一键批量推送&quot;">​</a></h3><p>后台配置页面提供「立即推送」按钮，配置好 API Key 后可随时手动触发：</p><p>— Bing 推送面板和 IndexNow 推送面板各自拥有独立的立即推送按钮；<br> — 点击后立即从数据库取出所有未推送文章 URL，按配置的数量上限批量提交；<br> — 推送完成后刷新仪表盘数据，显示本次推送数量和执行结果。</p><h3 id="indexnow-密钥文件自动管理" tabindex="-1">IndexNow 密钥文件自动管理 <a class="header-anchor" href="#indexnow-密钥文件自动管理" aria-label="Permalink to &quot;IndexNow 密钥文件自动管理&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-8.png" alt=""></p><p>IndexNow 协议要求网站根目录存在一个以 API Key 命名的 <code>.txt</code> 验证文件：</p><p>— 保存 IndexNow 配置时，插件自动在网站根目录创建或更新密钥文件，内容与配置中的 Key 保持一致；<br> — 修改 API Key 时自动删除旧密钥文件并创建新文件，同时清理其他历史密钥文件避免冗余；<br> — 每次推送前先通过 cURL 模拟搜索引擎自检密钥文件是否可公开访问（HTTP 200 且内容匹配），验证通过后才发起推送，提前发现配置问题。</p><h3 id="外部-api-调用端点" tabindex="-1">外部 API 调用端点 <a class="header-anchor" href="#外部-api-调用端点" aria-label="Permalink to &quot;外部 API 调用端点&quot;">​</a></h3><p>插件内置独立 API 端点 <code>bing_api.php</code>，支持通过外部工具（如系统 Cron、第三方监控平台）远程触发 Bing 推送：</p><p>— 调用地址：<code>zb_users/plugin/bing_indexnow/bing_api.php?key=你的密钥</code>；<br> — 密钥在后台独立设置，与 Bing API Key 分离，安全隔离；<br> — 验证通过后按配置的数量上限批量推送，返回纯文本执行结果，方便脚本集成和日志记录。</p><h3 id="推送日志记录" tabindex="-1">推送日志记录 <a class="header-anchor" href="#推送日志记录" aria-label="Permalink to &quot;推送日志记录&quot;">​</a></h3><p>每次推送的结果和状态均记录到 JSON 日志文件中：</p><p>— Bing 推送记录保存至 <code>cache/logs/bing_push_state.json</code>，含推送时间、推送数量、剩余额度等；<br> — IndexNow 推送记录保存至 <code>cache/logs/indexnow_push_state.json</code> 和 <code>indexnow_push_log.json</code>，包含 HTTP 状态码和失败原因；<br> — 日志自动限制最新 200 条记录，防止文件无限增长。</p><h3 id="管理后台开关" tabindex="-1">管理后台开关 <a class="header-anchor" href="#管理后台开关" aria-label="Permalink to &quot;管理后台开关&quot;">​</a></h3><p>— 顶部菜单显示开关（show_menu）：控制是否在后台顶部导航栏显示插件入口，关闭后仍可通过直接 URL 访问管理页；<br> — 卸载时清空数据开关（show_uninstall_clean）：开启后，卸载插件时会一并删除所有配置文件和缓存数据。</p><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><h3 id="第一步-安装插件" tabindex="-1">第一步：安装插件 <a class="header-anchor" href="#第一步-安装插件" aria-label="Permalink to &quot;第一步：安装插件&quot;">​</a></h3><p>将 <code>bing_indexnow</code> 文件夹上传至网站 <code>zb_users/plugin/</code> 目录，进入 Z-BlogPHP 后台「插件管理」页面，找到「Bing与IndexNow URL推送」并点击启用。</p><h3 id="第二步-配置-bing-推送" tabindex="-1">第二步：配置 Bing 推送 <a class="header-anchor" href="#第二步-配置-bing-推送" aria-label="Permalink to &quot;第二步：配置 Bing 推送&quot;">​</a></h3><p>进入后台「Bing与IndexNow推送」页面，默认显示 Bing 推送 Tab：</p><p>— 填入 Bing Webmaster Tools 的 API Key（获取方式：登录 Bing Webmaster Tools -&gt; 设置 -&gt; API 访问 -&gt; 获取 API Key）；<br> — 设置自动推送间隔（建议 5-30 分钟）和每次推送数量（建议 10-100 条）；<br> — 确认「自动推送开关」已开启（默认开启），点击「保存设置」；<br> — 保存后可看到仪表盘显示当日剩余额度和累计推送统计。</p><h3 id="第三步-配置-indexnow-推送" tabindex="-1">第三步：配置 IndexNow 推送 <a class="header-anchor" href="#第三步-配置-indexnow-推送" aria-label="Permalink to &quot;第三步：配置 IndexNow 推送&quot;">​</a></h3><p>切换到 IndexNow 推送 Tab：</p><p>— 手动输入或点击「随机生成」按钮创建一个 32 位十六进制 API Key；<br> — 设置自动推送间隔和每次推送数量（默认与 Bing 一致，可独立调整）；<br> — 确认「自动推送开关」已开启，点击「保存设置」；<br> — 保存时插件自动在网站根目录创建密钥验证文件（<code>你的Key.txt</code>），推送前自动验证文件可访问性。</p><h3 id="第四步-验证推送效果" tabindex="-1">第四步：验证推送效果 <a class="header-anchor" href="#第四步-验证推送效果" aria-label="Permalink to &quot;第四步：验证推送效果&quot;">​</a></h3><p>— 发布一篇新文章，插件会自动向两个通道提交该文章 URL；<br> — 进入后台插件页面查看仪表盘，确认累计推送数量增加；<br> — 如需主动推送旧文章，点击「立即推送」按钮一次性批量提交所有未推送 URL；<br> — 也可配置外部 Cron 任务调用 <code>bing_api.php?key=你的密钥</code> 定期触发推送。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>— 本插件依赖 PHP cURL 扩展与外部 API 通信，请确保服务器已启用 cURL 扩展；<br> — Bing 推送每日有额度限制（通常为每日 10,000 条），超出额度后 API 会拒绝请求，插件会自动记录剩余额度；<br> — IndexNow 推送无每日额度限制，但要求密钥验证文件可通过公网 HTTP 访问（搜索引擎需读取该文件验证域名所有权）；<br> — 如果网站使用了 CDN 或缓存插件，请确保根目录的 <code>.txt</code> 密钥文件不被缓存或重定向，否则 IndexNow 推送会因验证失败而中断；<br> — 访客触发型定时推送依赖于前台页面访问，日访问量极低的网站建议额外配置外部 Cron 调用 <code>bing_api.php</code> 以保证推送及时性；<br> — 推送日志和状态文件存储在插件目录下的 <code>cache/</code> 子目录中，请确保 PHP 对该目录有写入权限。</p><h2 id="反馈与支持" tabindex="-1">反馈与支持 <a class="header-anchor" href="#反馈与支持" aria-label="Permalink to &quot;反馈与支持&quot;">​</a></h2><p>— 作者：softbangong<br> — 作者网站：softbangong.com<br> — 作者网站：softbangong.top<br> — 邮箱：<a href="mailto:yunjuliangpin@163.com" target="_blank" rel="noreferrer">yunjuliangpin@163.com</a></p><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><h3 id="v1-0-0-2026-07-05" tabindex="-1">v1.0.0（2026-07-05） <a class="header-anchor" href="#v1-0-0-2026-07-05" aria-label="Permalink to &quot;v1.0.0（2026-07-05）&quot;">​</a></h3><p>— 初始版本发布；<br> — 支持 Bing Webmaster API URL 推送，含实时额度查询、手动推送和访客驱动定时推送；<br> — 支持 IndexNow 协议推送，覆盖 Bing、Yandex、Seznam、Naver 搜索引擎；<br> — 双通道独立配置，各自拥有独立的 API Key、推送间隔、推送数量和自动开关；<br> — 新文章发布自动推送（PostSucceed 钩子），发布即提交；<br> — 数据库标记防重复推送，推送状态跨定时/手动共享；<br> — IndexNow 密钥文件自动创建、更新和清理，推送前自检验证；<br> — 外部 API 端点（bing_api.php），支持第三方定时任务调用；<br> — 顶部菜单显示开关和卸载数据清理开关。</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2975.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2975.html</a></p>',59)])])}const p=a(i,[["render",t]]);export{c as __pageData,p as default};
